/**
 * Apply scheduled seat updates after month tick (current polling).
 * Guild: each month, 1/4 of seats reallocated silently (no election event).
 * Executive: full refresh in December. Districts: per DISTRICT_ELECTION_MONTH.
 */
Q.runScheduledElections = function(opts) {
    opts = opts || {}
    const month = opts.month != null ? opts.month : (Q.month || 1)
    const year = opts.year != null ? opts.year : (Q.year || 2300)
    const report = {
        month,
        year,
        skipped: false,
        executive: false,
        districts: [],
        any: false,
        lines: [],
    }

    if (
        !opts.force
        && !Q.elections_allow_same_month_repeat
        && Q.elections_applied_month === month
        && Q.elections_applied_year === year
    ) {
        report.skipped = true
        report.any = false
        for (const did of DISTRICT_IDS) {
            Q['election_show_' + did] = 0
        }
        return report
    }

    for (const did of DISTRICT_IDS) {
        Q['election_show_' + did] = 0
    }

    const results = runElectionsAndWriteQ({
        month,
        allDistricts: false,
        commitSeats: false,
    })

    for (const g of GUILD_KEYS) {
        const current = Object.fromEntries(
            PARTY_KEYS.map((k) => [k, Q[g + '_' + k] || 0])
        )
        const pollVotes = results.guild.byGuild[g] || zeroPartyVotes()
        const newSeats = rotateGuildSeatsQuarter(current, pollVotes, GUILD_SEATS)
        for (const k of PARTY_KEYS) {
            Q[g + '_' + k] = newSeats[k]
        }
    }

    if (month === EXEC_ELECTION_MONTH) {
        const ex = results.executive.seats
        for (const k of PARTY_KEYS) {
            Q['Exec_' + k] = ex[k]
        }
        report.executive = true
        report.lines.push('The Executive Council was re-elected for the coming year.')
    }

    for (const did of DISTRICT_IDS) {
        if (DISTRICT_ELECTION_MONTH[did] !== month) { continue }
        const run = results.districts[did]
        if (!run || !run.seats || !run.seats[did]) { continue }
        const oldSeats = Object.fromEntries(
            PARTY_KEYS.map((k) => [k, Q[did + '_' + k] || 0])
        )
        const ds = run.seats[did]
        const votes = run.byDistrict[did] || zeroPartyVotes()
        for (const k of PARTY_KEYS) {
            Q[did + '_' + k] = ds[k]
        }
        report.districts.push(did)
        publishDistrictElectionReport(did, votes, oldSeats, ds)
    }

    Q.elections_applied_month = month
    Q.elections_applied_year = year

    report.any = report.executive || report.districts.length > 0
    if (report.any) {
        Q.elections_this_month = 1
        Q.election_report = report.lines.join('\n\n')
    } else {
        Q.elections_this_month = 0
        Q.election_report = ''
    }
    return report
}

